const cacheDir = path.join(os.homedir(), '.cache', 'gad');
fs.mkdirSync(cacheDir, { recursive: true });

const oldPath = path.join(cacheDir, `pressure-${projectId.replace(/-/g, '_')}.json`);
const newPath = path.join(cacheDir, `pressure-${projectId}.json`);

let base = { breakdown: { rate_limits: 0, open_handoffs: 0, handoffs_with_unclaims: 0, worker_failures: 0, errors_recent: 0, errors_open: 0 } };
