try {
  const out = execSync(`gad evolution scan --projectid ${projectId} --json`, { stdio: ['ignore', 'pipe', 'ignore'] }).toString();
  scan = JSON.parse(out);
} catch (e) {}

const opScore = Number(base.score) || 0;
const evoScore = Math.min(1, (scan.candidateCount || 0) * 0.2 + (scan.shedCount || 0) / 200);
const score = Math.min(1, Math.max(opScore, evoScore));

const topPhase = (scan.scan && scan.scan.candidates && scan.scan.candidates[0])
  ? String(scan.scan.candidates[0].phase || 'placeholder')
  : (base.top_phase || 'placeholder');

const snapshot = {
  updated_at: new Date().toISOString(),
  projectid: projectId,
  score,
  top_phase: topPhase,
  top_phase_score: scan.candidateCount > 0 ? Math.min(1, scan.candidateCount * 0.25) : 0,
  breakdown: {
    ...base.breakdown,
    evo_candidates: scan.candidateCount || 0,
    evo_shed: scan.shedCount || 0,
  },
};

fs.writeFileSync(newPath, JSON.stringify(snapshot, null, 2));
console.log('Wrote', newPath);
console.log(JSON.stringify(snapshot, null, 2));
